@pytest.mark.parametrize("flag", [True, False, None])
def test_streaming_async_metadata(flag):
    from openai.types.responses import ResponseOutputItemAddedEvent
    item = {"type":"function_call", "id":"fc_holdout", "call_id":"call_holdout", "name":"lookup", "arguments":"{}"}
    if flag is not None:
        item["async"] = flag
    event = ResponseOutputItemAddedEvent.model_validate({"type":"response.output_item.added", "output_index":0, "sequence_number":0, "item":item})
    _, _, _, generation = _convert_responses_chunk_to_generation_chunk(event, -1, -1, -1, output_version="responses/v1")
    block = generation.message.content[0]
    assert block["call_id"] == "call_holdout"
    if flag is None:
        assert "async" not in block
    else:
        assert block["async"] is flag

@pytest.mark.parametrize("flag", [True, False])
def test_standard_content_roundtrip_async_false_and_true(flag):
    from langchain_openai.chat_models._compat import _convert_from_v1_to_responses
    message = AIMessage(content=[{"type":"function_call", "name":"lookup", "arguments":"{}", "call_id":"call_holdout", "id":"fc_holdout", "async":flag}], tool_calls=[{"id":"call_holdout", "name":"lookup", "args":{}, "type":"tool_call"}], response_metadata={"model_provider":"openai"})
    blocks = message.content_blocks
    assert blocks[0]["extras"]["async"] is flag
    restored = _convert_from_v1_to_responses(blocks, [])
    assert restored[0]["async"] is flag
    assert restored[0]["call_id"] == "call_holdout"


@pytest.mark.parametrize("flag", [True, False])
def test_declaration_false_is_preserved(flag):
    from langchain_core.tools import tool
    @tool(extras={"async":flag})
    def lookup(query: str) -> str:
        """Look up a value."""
        return query
    model = ChatOpenAI(model=OPENAI_TEST_MODEL, use_responses_api=True)
    binding = model.bind_tools([lookup])
    payload = binding._get_request_payload("offline", **binding.kwargs)
    assert payload["tools"][0]["async"] is flag

def test_previous_exports_retained():
    from langchain_fireworks import __all__
    assert {"__version__", "ChatFireworks", "Fireworks", "FireworksEmbeddings", "FireworksRerank"} <= set(__all__)
